def block_quadrant(r, c):
    """Return block's quadrant: A=top-left, B=top-right, C=bottom-left, D=bottom-right"""
    # Block spans rows r, r+1 and cols c, c+1
    # Check which quadrant each cell belongs to
    cells = [(r, c), (r, c+1), (r+1, c), (r+1, c+1)]
    upper_cells = [p for p in cells if p[0] <= center_r]
    lower_cells = [p for p in cells if p[0] > center_r]
    left_cells = [p for p in cells if p[1] <= center_c]
    right_cells = [p for p in cells if p[1] > center_c]

    upper_cnt = len(upper_cells)
    lower_cnt = len(lower_cells)
    left_cnt = len(left_cells)
    right_cnt = len(right_cells)

    top = upper_cnt > lower_cnt
    on_right = right_cnt > left_cnt

    if top:
        if on_right:
            return 'TR'
        else:
            return 'TL'
    else:
        if on_right:
            return 'BR'
        else:
            return 'BL'

    for cell in cells:
        row_idx = cell[0]
        col_idx = cell[1]
        if row_idx > center_r:
            # bottom half
            if col_idx > center_c:
                return 'BR'
            else:
                return 'BL'
        else:
            # top half
            if col_idx > center_c:
                return 'TR'
            else:
                return 'TL'

