test_blocks = [(1, 7), (1, 13), (2, 2), (4, 4), (4, 11), (5, 0), (5, 8)]

def block_diag_distance(b1, b2):
    """Calculate a distance metric between blocks"""
    r1, c1 = b1
    r2, c2 = b2
    # Check if blocks touch or overlap
    if r1 == r2 and abs(c1 - c2) < 2:
        return "adjacent_horiz"
    if abs(r1 - r2) == 1 and abs(c1 - c2) < 2:
        return "adjacent_vert"
    if r1 == r2+1 and abs(c1 - c2) < 2:
        return "touching_top"
    if r1 == r2-1 and abs(c1 - c2) < 2:
        return "touching_bottom"
    # Vertical or horizontal overlap
    if c1 == c2 and 0 <= r2 < r1+2:
        return "vert_overlap"
    if c1 == c2 and 0 <= r1 < r2+2:
        return "vert_overlap"
    if r1 == r2 - 2 or r2 == r1 - 2:
        return "vert_1gap"  # Exactly 1 row gap
    if r1 == r2 + 2 or r2 == r1 + 2:
        return "vert_1gap"
    # Horizontal overlap same row
    if abs(c1 - c2) == 2:
        return "horiz_1gap"
    if abs(c1 - c2) == 3:
        return "horiz_2gap"

    return "far"

# Count how many other blocks each block is close to
